/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var hasProp = require( '@stdlib/assert/has-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var QuantitativeScale = require( '@stdlib/plot/vega/scale/quantitative' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );
var TYPE = require( './type/type.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getConstant = require( './constant/get.js' );
var setConstant = require( './constant/set.js' );

var getProperties = require( './properties/get.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );


// VARIABLES //

var debug = logger( 'vega:symmetric-log-scale:main' );


// MAIN //

/**
* Logarithmic scale constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - scale name
* @param {(Collection|Object|Signal)} [options.bins] - bin boundaries over the scale domain
* @param {boolean} [options.clamp=false] - boolean indicating whether to clamp output values to the scale range
* @param {number} [options.constant=1] - constant which is used by the scale when determining the slope of the symlog function around zero
* @param {(Collection|Object|Signal)} [options.domain] - domain of associated data values
* @param {number} [options.domainMax] - maximum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMin] - minimum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMid] - single mid-point value inserted into a two-element domain
* @param {Collection} [options.domainRaw] - array of raw domain values which overrides the `domain` property
* @param {(string|Object)} [options.interpolate] - scale range interpolation method
* @param {(boolean|number|Signal)} [options.nice=false] - scale domain "nicing"
* @param {number} [options.padding] - scale domain padding (in pixels)
* @param {(Collection|Object|Signal|string)} [options.range] - scale range
* @param {boolean} [options.reverse=false] - boolean indicating whether to reverse the order of the scale range
* @param {boolean} [options.round=false] - boolean indicating whether to round numeric output values to integers
* @param {boolean} [options.zero] - boolean indicating whether the scale domain should include zero
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {SymLogScale} scale instance
*
* @example
* var scale = new SymLogScale({
*     'name': 'xScale'
* });
* // returns <SymLogScale>
*/
function SymLogScale( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof SymLogScale ) ) {
		return new SymLogScale( options );
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasProp( options, 'type' ) && options.type !== TYPE ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be equal to "%s". Option: `%s`.', 'type', TYPE, options.type ) );
	}
	// Check for required properties...
	if ( !hasProp( options, 'name' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the scale name.' );
	}
	QuantitativeScale.call( this, {
		'name': options.name
	});
	this._type = TYPE;

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from a parent prototype.
*/
inherit( SymLogScale, QuantitativeScale );

/**
* Constructor name.
*
* @private
* @name name
* @memberof SymLogScale
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( SymLogScale, 'name', 'SymLogScale' );

/**
* The constant which is used by the scale when determining the slope of the symlog function around zero.
*
* @name constant
* @memberof SymLogScale.prototype
* @type {number}
* @default 1
*
* @example
* var scale = new SymLogScale({
*     'name': 'xScale',
*     'constant': 2
* });
*
* var v = scale.constant;
* // returns 2
*/
setReadWriteAccessor( SymLogScale.prototype, 'constant', getConstant, setConstant );

/**
* Scale properties.
*
* @name properties
* @memberof SymLogScale.prototype
* @type {Array<string>}
*
* @example
* var scale = new SymLogScale({
*     'name': 'xScale'
* });
*
* var v = scale.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( SymLogScale.prototype, 'properties', getProperties );

/**
* Scale type.
*
* @name type
* @memberof SymLogScale.prototype
* @type {string}
* @default 'symlog'
*
* @example
* var scale = new SymLogScale({
*     'name': 'xScale'
* });
*
* var v = scale.type;
* // returns 'symlog'
*/
setReadWriteAccessor( SymLogScale.prototype, 'type', getType, setType );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof SymLogScale.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var scale = new SymLogScale({
*     'name': 'xScale'
* });
*
* var v = scale.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( SymLogScale.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = SymLogScale;
